      const tableCheck = await executeQuery2(repo.id, `MATCH (e:${EMBEDDING_TABLE_NAME}) RETURN COUNT(*) AS cnt LIMIT 1`);
      if (!tableCheck.length || (tableCheck[0].cnt ?? tableCheck[0][0]) === 0)
        return [];
      const { embedQuery: embedQuery2, getEmbeddingDims: getEmbeddingDims2 } = await Promise.resolve().then(() => (init_embedder(), exports_embedder));
      const queryVec = await embedQuery2(query);
      const dims = getEmbeddingDims2();
