          const nodeQuery = label === "File" ? `MATCH (n:File {id: $nodeId}) RETURN n.name AS name, n.filePath AS filePath` : `MATCH (n:\`${label}\` {id: $nodeId}) RETURN n.name AS name, n.filePath AS filePath`;
          const nodeRows = await executeParameterized(repo.id, nodeQuery, { nodeId });
